{
  "name": "@botkinmoscow/opencode-emias",
  "version": "0.1.1",
  "description": "OpenCode plugin for direct access to EMIAS MosAI with automatic authentication",
  "type": "module",
  "exports": "./dist/index.js",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "prepack": "npm run build"
  },
  "repository": {
    "type": "git",
    "url": "git+https://gitlab.com/botkinmoscow/opencode-emias.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "emias",
    "mosai"
  ],
  "license": "UNLICENSED",
  "engines": {
    "node": ">=20"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.4",
    "@types/node": "^24.0.0",
    "typescript": "^5.9.0"
  }
}
